                    ->transform.position.y
                - ((AttachmentSample*)((char*)primary_samples + curve_sample_offset) - 1)
                    ->transform.position.y,
            ((AttachmentSample*)((char*)primary_samples + curve_sample_offset))
                    ->transform.position.z
